package com.simibubi.create.content.equipment.toolbox;

import java.util.ArrayList;
import java.util.List;
import java.util.Objects;
import java.util.function.Consumer;

import org.jetbrains.annotations.ApiStatus.ScheduledForRemoval;
import org.jetbrains.annotations.NotNull;

import com.mojang.serialization.Codec;
import com.mojang.serialization.codecs.RecordCodecBuilder;
import com.simibubi.create.AllDataComponents;
import com.simibubi.create.AllItems;
import com.simibubi.create.foundation.item.ItemHelper;
import com.simibubi.create.foundation.item.ItemSlots;

import net.createmod.catnip.codecs.stream.CatnipStreamCodecBuilders;
import net.createmod.catnip.nbt.NBTHelper;
import net.minecraft.core.HolderLookup;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.nbt.Tag;
import net.minecraft.network.RegistryFriendlyByteBuf;
import net.minecraft.network.codec.StreamCodec;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.component.ItemContainerContents;

import net.neoforged.neoforge.items.ItemStackHandler;

// TODO - This should use NonNullList<ItemStack>
public class ToolboxInventory extends ItemStackHandler {
	public static final int STACKS_PER_COMPARTMENT = 4;
	public static final Codec<ToolboxInventory> CODEC = RecordCodecBuilder.create(instance -> instance.group(
		ItemSlots.maxSizeCodec(8 * STACKS_PER_COMPARTMENT).fieldOf("items").forGetter(ItemSlots::fromHandler),
		ItemStack.OPTIONAL_CODEC.listOf().fieldOf("filters").forGetter(toolbox -> toolbox.filters)
	).apply(instance, ToolboxInventory::deserialize));

	public static final StreamCodec<RegistryFriendlyByteBuf, ToolboxInventory> STREAM_CODEC = StreamCodec.composite(
		ItemSlots.STREAM_CODEC, ItemSlots::fromHandler,
		CatnipStreamCodecBuilders.list(ItemStack.OPTIONAL_STREAM_CODEC), toolbox -> toolbox.filters,
		ToolboxInventory::deserialize
	);

	@ScheduledForRemoval(inVersion = "1.21.1+ Port")
	@Deprecated(since = "6.0.6", forRemoval = true)
	public static final Codec<ToolboxInventory> BACKWARDS_COMPAT_CODEC = Codec.withAlternative(
		CODEC,
		ItemContainerContents.CODEC.xmap(i -> {
			ToolboxInventory inv = new ToolboxInventory(null);
			ItemHelper.fillItemStackHandler(i, inv);
			return inv;
		}, ItemHelper::containerContentsFromHandler)
	);

	List<ItemStack> filters;
	boolean settling;
	private final ToolboxBlockEntity blockEntity;

	private boolean limitedMode;

	public ToolboxInventory(ToolboxBlockEntity be) {
		super(8 * STACKS_PER_COMPARTMENT);
		this.blockEntity = be;
		limitedMode = false;
		filters = new ArrayList<>();
		settling = false;
		for (int i = 0; i < 8; i++)
			filters.add(ItemStack.EMPTY);
	}

	public void inLimitedMode(Consumer<ToolboxInventory> action) {
		limitedMode = true;
		action.accept(this);
		limitedMode = false;
	}

	public void settle(int compartment) {
		int totalCount = 0;
		boolean valid = true;
		boolean shouldBeEmpty = false;
		ItemStack sample = ItemStack.EMPTY;

		for (int i = 0; i < STACKS_PER_COMPARTMENT; i++) {
			ItemStack stackInSlot = getStackInSlot(compartment * STACKS_PER_COMPARTMENT + i);
			totalCount += stackInSlot.getCount();
			if (!shouldBeEmpty)
				shouldBeEmpty = stackInSlot.isEmpty() || stackInSlot.getCount() != stackInSlot.getMaxStackSize();
			else if (!stackInSlot.isEmpty()) {
				valid = false;
				sample = stackInSlot;
			}
		}

		if (valid)
			return;

		settling = true;
		if (!sample.isStackable()) {
			for (int i = 0; i < STACKS_PER_COMPARTMENT; i++) {
				if (!getStackInSlot(compartment * STACKS_PER_COMPARTMENT + i).isEmpty())
					continue;
				for (int j = i + 1; j < STACKS_PER_COMPARTMENT; j++) {
					ItemStack stackInSlot = getStackInSlot(compartment * STACKS_PER_COMPARTMENT + j);
					if (stackInSlot.isEmpty())
						continue;
					setStackInSlot(compartment * STACKS_PER_COMPARTMENT + i, stackInSlot);
					setStackInSlot(compartment * STACKS_PER_COMPARTMENT + j, ItemStack.EMPTY);
					break;
				}
			}
		} else {
			for (int i = 0; i < STACKS_PER_COMPARTMENT; i++) {
				ItemStack copy = totalCount <= 0 ? ItemStack.EMPTY
					: sample.copyWithCount(Math.min(totalCount, sample.getMaxStackSize()));
				setStackInSlot(compartment * STACKS_PER_COMPARTMENT + i, copy);
				totalCount -= copy.getCount();
			}
		}
		settling = false;
		notifyUpdate();
	}

	@Override
	public boolean isItemValid(int slot, ItemStack stack) {
		if (!stack.getItem().canFitInsideContainerItems())
			return false;

		if (slot < 0 || slot >= getSlots())
			return false;
		int compartment = slot / STACKS_PER_COMPARTMENT;
		ItemStack filter = filters.get(compartment);
		if (limitedMode && filter.isEmpty())
			return false;
		if (filter.isEmpty() || ToolboxInventory.canItemsShareCompartment(filter, stack))
			return super.isItemValid(slot, stack);
		return false;
	}

	@Override
	public void setStackInSlot(int slot, ItemStack stack) {
		super.setStackInSlot(slot, stack);
		int compartment = slot / STACKS_PER_COMPARTMENT;
		if (!stack.isEmpty() && filters.get(compartment)
			.isEmpty()) {
			filters.set(compartment, stack.copyWithCount(1));
			notifyUpdate();
		}
	}

	@Override
	public @NotNull ItemStack insertItem(int slot, @NotNull ItemStack stack, boolean simulate) {
		ItemStack insertItem = super.insertItem(slot, stack, simulate);
		if (insertItem.getCount() != stack.getCount()) {
			int compartment = slot / STACKS_PER_COMPARTMENT;
			if (!stack.isEmpty() && filters.get(compartment)
				.isEmpty()) {
				filters.set(compartment, stack.copyWithCount(1));
				notifyUpdate();
			}
		}
		return insertItem;
	}

	@Override
	public @NotNull CompoundTag serializeNBT(@NotNull HolderLookup.Provider registries) {
		CompoundTag compound = super.serializeNBT(registries);
		compound.put("Compartments", NBTHelper.writeItemList(filters, registries));
		return compound;
	}

	@Override
	protected void onContentsChanged(int slot) {
		if (!settling && (blockEntity == null || !blockEntity.getLevel().isClientSide))
			settle(slot / STACKS_PER_COMPARTMENT);
		notifyUpdate();
		super.onContentsChanged(slot);
	}

	@Override
	public void deserializeNBT(@NotNull HolderLookup.Provider registries, CompoundTag nbt) {
		filters = NBTHelper.readItemList(nbt.getList("Compartments", Tag.TAG_COMPOUND), registries);
		if (filters.size() != 8) {
			filters.clear();
			for (int i = 0; i < 8; i++)
				filters.add(ItemStack.EMPTY);
		}
		super.deserializeNBT(registries, nbt);
	}

	public ItemStack distributeToCompartment(@NotNull ItemStack stack, int compartment, boolean simulate) {
		if (stack.isEmpty())
			return stack;
		if (filters.get(compartment)
			.isEmpty())
			return stack;

		for (int i = STACKS_PER_COMPARTMENT - 1; i >= 0; i--) {
			int slot = compartment * STACKS_PER_COMPARTMENT + i;
			stack = insertItem(slot, stack, simulate);
			if (stack.isEmpty())
				return ItemStack.EMPTY;
		}

		return stack;
	}

	public ItemStack takeFromCompartment(int amount, int compartment, boolean simulate) {
		if (amount == 0)
			return ItemStack.EMPTY;

		int remaining = amount;
		ItemStack lastValid = ItemStack.EMPTY;

		for (int i = STACKS_PER_COMPARTMENT - 1; i >= 0; i--) {
			int slot = compartment * STACKS_PER_COMPARTMENT + i;
			ItemStack extracted = extractItem(slot, remaining, simulate);
			remaining -= extracted.getCount();
			if (!extracted.isEmpty())
				lastValid = extracted;
			if (remaining == 0)
				return lastValid.copyWithCount(amount);
		}

		if (remaining == amount)
			return ItemStack.EMPTY;

		return lastValid.copyWithCount(amount - remaining);
	}

	public static ItemStack cleanItemNBT(ItemStack stack) {
		if (AllItems.BELT_CONNECTOR.isIn(stack))
			stack.remove(AllDataComponents.BELT_FIRST_SHAFT);
		return stack;
	}

	public static boolean canItemsShareCompartment(ItemStack stack1, ItemStack stack2) {
		if (!stack1.isStackable() && !stack2.isStackable() && stack1.isDamageableItem() && stack2.isDamageableItem())
			return stack1.getItem() == stack2.getItem();
		if (AllItems.BELT_CONNECTOR.isIn(stack1) && AllItems.BELT_CONNECTOR.isIn(stack2))
			return true;
		return ItemStack.isSameItemSameComponents(stack1, stack2);
	}

	private void notifyUpdate() {
		if (blockEntity != null)
			blockEntity.notifyUpdate();
	}

	private static ToolboxInventory deserialize(ItemSlots slots, List<ItemStack> filters) {
		ToolboxInventory inventory = new ToolboxInventory(null);
		inventory.settling = true;
		slots.forEach(inventory::setStackInSlot);
		inventory.settling = false;
		inventory.filters = new ArrayList<>(filters);
		return inventory;
	}

	@Override
	public final boolean equals(Object o) {
		if (!(o instanceof ToolboxInventory that)) return false;

		return settling == that.settling && limitedMode == that.limitedMode && ItemStack.listMatches(filters, that.filters)
			&& Objects.equals(blockEntity, that.blockEntity);
	}

	@Override
	public int hashCode() {
		int result = filters.hashCode();
		result = 31 * result + Boolean.hashCode(settling);
		result = 31 * result + Objects.hashCode(blockEntity);
		result = 31 * result + Boolean.hashCode(limitedMode);
		return result;
	}

package com.simibubi.create.foundation.item;

import java.util.HashMap;
import java.util.Map;
import java.util.function.IntFunction;

import com.mojang.serialization.Codec;
import com.mojang.serialization.DataResult;
import com.mojang.serialization.codecs.RecordCodecBuilder;
import com.simibubi.create.foundation.codec.CreateCodecs;

import it.unimi.dsi.fastutil.ints.Int2ObjectMap;
import it.unimi.dsi.fastutil.ints.Int2ObjectOpenHashMap;
import net.minecraft.network.RegistryFriendlyByteBuf;
import net.minecraft.network.codec.ByteBufCodecs;
import net.minecraft.network.codec.StreamCodec;
import net.minecraft.util.ExtraCodecs;
import net.minecraft.world.item.ItemStack;

import net.neoforged.neoforge.items.IItemHandler;
import net.neoforged.neoforge.items.IItemHandlerModifiable;

/**
 * Utility class representing non-empty slots in an item inventory.
 */
public class ItemSlots {
	public static final Codec<ItemSlots> CODEC = RecordCodecBuilder.create(instance -> instance.group(
		Codec.unboundedMap(CreateCodecs.boundedIntStr(0), ItemStack.CODEC).fieldOf("items").forGetter(ItemSlots::toBoxedMap),
		ExtraCodecs.NON_NEGATIVE_INT.fieldOf("size").forGetter(ItemSlots::getSize)
	).apply(instance, ItemSlots::deserialize));

	public static final StreamCodec<RegistryFriendlyByteBuf, ItemSlots> STREAM_CODEC = StreamCodec.composite(
		ByteBufCodecs.map(HashMap::new, ByteBufCodecs.INT, ItemStack.STREAM_CODEC), ItemSlots::toBoxedMap,
		ByteBufCodecs.INT, ItemSlots::getSize,
		ItemSlots::deserialize
	);

	private final Int2ObjectMap<ItemStack> map;
	private int size;

	public ItemSlots() {
		this.map = new Int2ObjectOpenHashMap<>();
		this.size = 0;
	}

	public void set(int slot, ItemStack stack) {
		if (slot < 0) {
			throw new IllegalArgumentException("Slot must be positive");
		} else if (!stack.isEmpty()) {
			this.map.put(slot, stack);
			this.size = Math.max(this.size, slot + 1);
		}
	}

	public int getSize() {
		return this.size;
	}

	public void setSize(int size) {
		if (size <= this.getHighestSlot()) {
			throw new IllegalStateException("cannot set size to below the highest slot");
		}
		this.size = size;
	}

	public void forEach(SlotConsumer consumer) {
		for (Int2ObjectMap.Entry<ItemStack> entry : this.map.int2ObjectEntrySet()) {
			consumer.accept(entry.getIntKey(), entry.getValue());
		}
	}

	private int getHighestSlot() {
		return this.map.keySet().intStream().max().orElse(-1);
	}

	public <T extends IItemHandlerModifiable> T toHandler(IntFunction<T> factory) {
		T handler = factory.apply(this.size);
		this.forEach(handler::setStackInSlot);
		return handler;
	}

	public static ItemSlots fromHandler(IItemHandler handler) {
		ItemSlots slots = new ItemSlots();
		slots.setSize(handler.getSlots());
		for (int i = 0; i < handler.getSlots(); i++) {
			ItemStack stack = handler.getStackInSlot(i);
			if (!stack.isEmpty()) {
				slots.set(i, stack.copy());
			}
		}
		return slots;
	}

	public Map<Integer, ItemStack> toBoxedMap() {
		Map<Integer, ItemStack> map = new HashMap<>();
		this.forEach(map::put);
		return map;
	}

	public static ItemSlots fromBoxedMap(Map<Integer, ItemStack> map) {
		ItemSlots slots = new ItemSlots();
		map.forEach(slots::set);
		return slots;
	}

	public static Codec<ItemSlots> maxSizeCodec(int maxSize) {
		return CODEC.validate(slots -> slots.size <= maxSize
			? DataResult.success(slots)
			: DataResult.error(() -> "Slots above maximum of " + maxSize));
	}

	private static ItemSlots deserialize(Map<Integer, ItemStack> map, int size) {
		ItemSlots slots = fromBoxedMap(map);
		slots.setSize(size);
		return slots;
	}

	@FunctionalInterface
	public interface SlotConsumer {
		void accept(int slot, ItemStack stack);
	}
}

@Override
public void initialize() {
	super.initialize();
	ToolboxHandler.onLoad(this);
}

@Override
public void invalidate() {
	super.invalidate();
	ToolboxHandler.onUnload(this);
}

@Override
public void tick() {
	super.tick();

	if (level.isClientSide)
		tickAudio();
	if (!level.isClientSide)
		tickPlayers();

	lid.chase(openTracker.openCount > 0 ? 1 : 0, 0.2f, Chaser.LINEAR);
	drawers.chase(openTracker.openCount > 0 ? 1 : 0, 0.2f, Chaser.EXP);
	lid.tickChaser();
	drawers.tickChaser();
}

private void tickPlayers() {
	boolean update = false;

	for (Iterator<Entry<Integer, WeakHashMap<Player, Integer>>> toolboxSlots = connectedPlayers.entrySet()
		.iterator(); toolboxSlots.hasNext(); ) {

		Entry<Integer, WeakHashMap<Player, Integer>> toolboxSlotEntry = toolboxSlots.next();
		WeakHashMap<Player, Integer> set = toolboxSlotEntry.getValue();
		int slot = toolboxSlotEntry.getKey();

		ItemStack referenceItem = inventory.filters.get(slot);
		boolean clear = referenceItem.isEmpty();

		for (Iterator<Entry<Player, Integer>> playerEntries = set.entrySet()
			.iterator(); playerEntries.hasNext(); ) {
			Entry<Player, Integer> playerEntry = playerEntries.next();

			Player player = playerEntry.getKey();
			int hotbarSlot = playerEntry.getValue();

			if (!clear && !ToolboxHandler.withinRange(player, this))
				continue;

			Inventory playerInv = player.getInventory();
			ItemStack playerStack = playerInv.getItem(hotbarSlot);

			if (clear || !playerStack.isEmpty()
				&& !ToolboxInventory.canItemsShareCompartment(playerStack, referenceItem)) {
				player.getPersistentData()
					.getCompound("CreateToolboxData")
					.remove(String.valueOf(hotbarSlot));
				playerEntries.remove();
				if (player instanceof ServerPlayer)
					ToolboxHandler.syncData(player);
				continue;
			}

			int count = playerStack.getCount();
			int targetAmount = (referenceItem.getMaxStackSize() + 1) / 2;

			if (count < targetAmount) {
				int amountToReplenish = targetAmount - count;

				if (isOpenInContainer(player)) {
					ItemStack extracted = inventory.takeFromCompartment(amountToReplenish, slot, true);
					if (!extracted.isEmpty()) {
						ToolboxHandler.unequip(player, hotbarSlot, false);
						ToolboxHandler.syncData(player);
						continue;
					}
				}

				ItemStack extracted = inventory.takeFromCompartment(amountToReplenish, slot, false);
				if (!extracted.isEmpty()) {
					update = true;
					ItemStack template = playerStack.isEmpty() ? extracted : playerStack;
					playerInv.setItem(hotbarSlot,
						template.copyWithCount(count + extracted.getCount()));
				}
			}

			if (count > targetAmount) {
				int amountToDeposit = count - targetAmount;
				ItemStack toDistribute = playerStack.copyWithCount(amountToDeposit);

				if (isOpenInContainer(player)) {
					int deposited = amountToDeposit - inventory.distributeToCompartment(toDistribute, slot, true)
						.getCount();
					if (deposited > 0) {
						ToolboxHandler.unequip(player, hotbarSlot, true);
						ToolboxHandler.syncData(player);
						continue;
					}
				}

				int deposited = amountToDeposit - inventory.distributeToCompartment(toDistribute, slot, false)
					.getCount();
				if (deposited > 0) {
					update = true;
					playerInv.setItem(hotbarSlot,
						playerStack.copyWithCount(count - deposited));
				}
			}
		}

		if (clear)
			toolboxSlots.remove();
	}

	if (update)

		sendData();

}

private boolean isOpenInContainer(Player player) {
	return player.containerMenu instanceof ToolboxMenu
		&& ((ToolboxMenu) player.containerMenu).contentHolder == this;
}

public void unequipTracked() {
	if (level.isClientSide)
		return;

	Set<ServerPlayer> affected = new HashSet<>();

	for (Entry<Integer, WeakHashMap<Player, Integer>> toolboxSlotEntry : connectedPlayers.entrySet()) {

		WeakHashMap<Player, Integer> set = toolboxSlotEntry.getValue();

		for (Entry<Player, Integer> playerEntry : set.entrySet()) {
			Player player = playerEntry.getKey();
			int hotbarSlot = playerEntry.getValue();

			ToolboxHandler.unequip(player, hotbarSlot, false);
			if (player instanceof ServerPlayer)
				affected.add((ServerPlayer) player);
		}
	}

	public void connectPlayer(int slot, Player player, int hotbarSlot) {
		if (level.isClientSide)
			return;
		WeakHashMap<Player, Integer> map = connectedPlayers.computeIfAbsent(slot, WeakHashMap::new);
		Integer previous = map.get(player);
		if (previous != null) {
			if (previous == hotbarSlot)
				return;
			ToolboxHandler.unequip(player, previous, false);
		}
		map.put(player, hotbarSlot);
	}

	public void readInventory(ToolboxInventory inv) {
		if (inv != null) {
			this.inventory.filters = new ArrayList<>(inv.filters);
			for (int i = 0; i < inv.getSlots(); i++)
				this.inventory.setStackInSlot(i, inv.getStackInSlot(i));
		}
	}

	public void setUniqueId(UUID uniqueId) {
		this.uniqueId = uniqueId;
	}

	public UUID getUniqueId() {
		return uniqueId;
	}

	public boolean isFullyInitialized() {
		// returns true when uniqueId has been initialized
		return uniqueId != null;
	}

	public void setCustomName(Component customName) {
		this.customName = customName;
	}

	@Override
	public Component getDisplayName() {
		return customName != null ? customName
			: AllBlocks.TOOLBOXES.get(getColor())
			.get()
			.getName();
	}

	@Override
	public Component getCustomName() {
		return customName;
	}

	@Override
	public boolean hasCustomName() {
		return customName != null;
	}

	@Override
	public Component getName() {
		return customName;
	}

	@SuppressWarnings("deprecation")
	@Override
	public void setBlockState(BlockState state) {
		super.setBlockState(state);
		colorProvider.reset();
	}

	@Override
	protected void applyImplicitComponents(DataComponentInput componentInput) {
		setUniqueId(componentInput.get(AllDataComponents.TOOLBOX_UUID));
		readInventory(componentInput.get(AllDataComponents.TOOLBOX_INVENTORY));
	}

	@Override
	protected void collectImplicitComponents(Builder components) {
		components.set(AllDataComponents.TOOLBOX_UUID, uniqueId);
		components.set(AllDataComponents.TOOLBOX_INVENTORY, inventory);
	}
}

public static final DataComponentType<ItemContainerContents> LINKED_CONTROLLER_ITEMS = register(
		"linked_controller_items",
		builder -> builder.persistent(ItemContainerContents.CODEC).networkSynchronized(ItemContainerContents.STREAM_CODEC)
);

public static final DataComponentType<ToolboxInventory> TOOLBOX_INVENTORY = register(
		"toolbox_inventory",
	builder -> builder.persistent(ToolboxInventory.BACKWARDS_COMPAT_CODEC).networkSynchronized(ToolboxInventory.STREAM_CODEC)
);

public static final DataComponentType<UUID> TOOLBOX_UUID = register(
		"toolbox_uuid",
		builder -> builder.persistent(UUIDUtil.CODEC).networkSynchronized(UUIDUtil.STREAM_CODEC)
